const hook = $('Suggest Webhook').first().json;
const body = hook.body && typeof hook.body === 'object' ? hook.body : hook;
const who = $('Whoami').first().json || {};
const userId = who.user_id ? String(who.user_id).trim() : null;
const filename = body && body.filename ? String(body.filename) : '';
const contentRaw = body && body.contentRaw != null ? String(body.contentRaw) : '';
const message = (body && body.message ? String(body.message) : ('suggest: ' + filename)).slice(0, 200);
// This endpoint can ONLY create a reader-feedback deposit:
//   articles/<slug>/<stamp>-eva-<hash>.jsonl
// Any other path is refused (422), so it can never write the genesis, a REC/INS,
// or anything outside an article's folder. It CREATES files (never overwrites),
// so it cannot mutate an existing event either. That is the whole capability of
// this webhook: drop one suggestion file into a story's folder.
const EVA_RE = /^articles\/[A-Za-z0-9][A-Za-z0-9-]*\/[0-9A-Za-z]+-eva-[0-9A-Za-z]+\.jsonl$/;
let reason = null, code = 200, line = '';
if (!userId) { reason = 'unverified — a valid Matrix access token is required'; code = 401; }
else if (!EVA_RE.test(filename)) { reason = 'forbidden path — this endpoint only writes articles/<slug>/<stamp>-eva-<hash>.jsonl'; code = 422; }
if (!reason) {
  const lines = contentRaw.split('\n').map(s => s.trim()).filter(Boolean);
  if (lines.length !== 1) { reason = 'one EVA event per deposit'; code = 422; }
  else {
    try {
      const ev = JSON.parse(lines[0]);
      if (!ev || ev.op !== 'EVA') { reason = 'not an EVA event'; code = 422; }
      else {
        // Stamp attribution from the verified token: you can only ever post as
        // yourself, never forge another contributor's handle into the record.
        ev.actor = userId;
        if (ev.operand && typeof ev.operand === 'object') ev.operand.author = userId;
        line = JSON.stringify(ev);
      }
    } catch (e) { reason = 'content is not a single JSON line'; code = 422; }
  }
}
const ok = !reason;
const contentBase64 = ok ? Buffer.from(line + '\n', 'utf8').toString('base64') : '';
return [{ json: { ok, reason, code, user_id: userId, filename, message, contentBase64 } }];

const gh = $input.first().json || {};
const v = $('Validate').first().json || {};
const errObj = gh.error;
const errMsg = (typeof errObj === 'string' ? errObj : (errObj && (errObj.message || errObj.description))) || gh.message || null;
const ctx = (errObj && (errObj.context || errObj.cause)) || {};
const ghStatus = Number(gh.status || gh.statusCode || gh.httpCode || (errObj && (errObj.httpCode || errObj.status || errObj.statusCode)) || ctx.httpCode || ctx.statusCode || 0) || null;
const commitSha = (gh.commit && gh.commit.sha) || (gh.content && gh.content.sha) || null;
const hasError = !!errObj || (ghStatus && ghStatus >= 400) || (!commitSha && !!errMsg);
return [{ json: {
  ok: !hasError,
  statusCode: hasError ? (ghStatus || 502) : 200,
  filename: v.filename, user: v.user_id, commit_sha: commitSha,
  gh_status: ghStatus, error: hasError ? (errMsg || 'github commit failed') : null
} }];
